\begin{bmatrix}
\omega \\
\dot{\omega}
\end{bmatrix}
+
\begin{bmatrix}
0 \\
\frac{1}{I}
\end{bmatrix}
T
}
\]

The output is:

\[
\boxed{y = \omega}
